static int handle_input(void) {
    char buf[10];
    ssize_t n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
    if (n > 0) {
        buf[n] = '\0';

        for (int i = 0; buf[i] != '\0'; i++) {
            char c = buf[i];

            if (c == 'q' || c == 'Q') {
                quit = 1;
                return 1;
            } else if (c == 'a' || c == 'A') {
                async_scroll = !async_scroll;
            } else if (c == 'b' || c == 'B') {
                bold_chars = !bold_chars;
            } else if (c == 'n' || c == 'N') {
                bold_chars = 0;
                all_bold = 0;
            } else if (c >= '0' && c <= '9') {
                delay = c - '0';
                if (delay < MIN_DELAY) delay = MIN_DELAY;
                if (delay > MAX_DELAY) delay = MAX_DELAY;
            } else if (c == '!') {
                current_color = COLOR_RED;
            } else if (c == '@') {
                current_color = COLOR_GREEN;
            } else if (c == '#') {
                current_color = COLOR_YELLOW;
            } else if (c == '$') {
                current_color = COLOR_BLUE;
            } else if (c == '%') {
                current_color = COLOR_MAGENTA;
            } else if (c == '^') {
                current_color = COLOR_CYAN;
            } else if (c == '&') {
                current_color = COLOR_WHITE;
            } else if (c == ')') {
                current_color = COLOR_BLACK;
            }
        }
    }
    return 0;
}

static void main_loop(void) {
    struct timeval tv;

    init_terminal();
    init_lines();

    clear_screen();

    if (lock_mode) {
        printf("\033[?1049h");
        printf("\033[2J\033[H");
        if (message) {
            print_center_message();
        } else {
            printf("CMatrix is running in lock mode.\n");
            printf("Press Ctrl+C to quit.\n");
        }
        printf("\033[?1049l");
        restore_terminal();
        return;
    }

    if (screensaver_mode) {
        printf("\033[?1049h");
        clear_screen();
        printf("\033[?1049l");
    }

    while (!quit) {
        /* Update display */
        if (change_chars) {
            for (int y = 0; y < num_lines; y++) {
                if (lines[y]) {
                    for (int x = 0; x < width; x++) {
                        lines[y][x] = get_random_char();
                    }
                }
            }
        }

        update_lines();
        draw_matrix();

        if (message) {
            print_center_message();
        }

        /* Handle input */
        if (!screensaver_mode) {
            handle_input();
        }

        /* Sleep for delay */
        tv.tv_sec = 0;
        tv.tv_usec = delay * 100000;
        select(STDIN_FILENO, NULL, NULL, NULL, &tv);
    }

    if (screensaver_mode) {
        printf("\033[?1049h");
        clear_screen();
        printf("\033[?1049l");
    }

    free_lines();
    restore_terminal();
}
```

