    if (lines) {
        for (int i = 0; i < num_lines; i++) {
            free(lines[i]);
        }
        free(lines);
    }

    lines = malloc(height * sizeof(char *));
    if (!lines) {
        return;
    }

    num_lines = height;
    for (int i = 0; i < height; i++) {
        lines[i] = malloc(width + 1);
        if (lines[i]) {
            lines[i][0] = get_random_char();
            for (int j = 1; j < width; j++) {
                lines[i][j] = ' ';
            }
            lines[i][width] = '\0';
        }
    }
}

/* Free lines */
static void free_lines(void) {
    if (lines) {
        for (int i = 0; i < num_lines; i++) {
            free(lines[i]);
        }
        free(lines);
        lines = NULL;
    }
}

/* Get random delay */
static int get_delay(void) {
    return delay;
}

/* Get random color */
static const char *get_random_color(void) {
    int r = rand() % 8;
    if (r == 0) return COLOR_GREEN;
    if (r == 1) return COLOR_RED;
    if (r == 2) return COLOR_BLUE;
    if (r == 3) return COLOR_WHITE;
    if (r == 4) return COLOR_YELLOW;
    if (r == 5) return COLOR_CYAN;
    if (r == 6) return COLOR_MAGENTA;
    return COLOR_BLACK;
}

/* Rainbow color */
static const char *get_rainbow_color(void) {
    static int hue = 0;
    hue = (hue + 1) % 360;
    return COLOR_GREEN;
}

/* Lambda color */
static const char *get_lambda_color(void) {
    return COLOR_GREEN;
}

/* Main loop */
static void main_loop(void) {
    struct timeval tv;
    fd_set readfds;
    int ret;

    init_lines();

    while (!quit) {
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        tv.tv_sec = 0;
        tv.tv_usec = get_delay() * 100000;

        ret = select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            break;
        }

        if (ret > 0 && !screensaver_mode) {
            char buf[10];
            ssize_t n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
            if (n > 0) {
                buf[n] = '\0';
                for (int i = 0; i < n; i++) {
                    char c = buf[i];
                    if (c == 'q' || c == 'Q') {
                        quit = 1;
                        break;
                    } else if (c == 'a' || c == 'A') {
                        async_scroll = !async_scroll;
                    } else if (c == 'b' || c == 'B') {
                        bold_chars = !bold_chars;
                    } else if (c == 'n') {
                        bold_chars = 0;
                        all_bold = 0;
                    } else if (c >= '0' && c <= '9') {
                        delay = c - '0';
                        if (delay > MAX_DELAY) delay = MAX_DELAY;
                        if (delay < MIN_DELAY) delay = MIN_DELAY;
                    } else if (c == '!') {
                        current_color = COLOR_RED;
                    } else if (c == '@') {
                        current_color = COLOR_GREEN;
                    } else if (c == '#') {
                        current_color = COLOR_YELLOW;
                    } else if (c == '$') {
                        current_color = COLOR_BLUE;
                    } else if (c == '%') {
                        current_color = COLOR_MAGENTA;
                    } else if (c == '^') {
                        current_color = COLOR_CYAN;
                    } else if (c == '&') {
                        current_color = COLOR_WHITE;
                    } else if (c == ')') {
                        current_color = COLOR_BLACK;
                    }
                }
            }
        }

        if (screensaver_mode) {
            char buf[10];
            ssize_t n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
            if (n > 0) {
                quit = 1;
                break;
            }
        }

        if (async_scroll) {
            int y = rand() % height;
            move_line_up(y);
            update_line(y);
        } else {
            move_matrix_up();
            update_matrix();
        }

        clear_screen();
        draw_matrix();
        print_center_message();
    }

    free_lines();
}

/* Print usage */
static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

/* Print version */
static void print_version(void) {
    printf("cmatrix version %s\n", VERSION);
}

/* Parse arguments */
static void parse_args(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) {
            async_scroll = 1;
        } else if (strcmp(argv[i], "-b") == 0) {
            bold_chars = 1;
        } else if (strcmp(argv[i], "-B") == 0) {
            all_bold = 1;
            bold_chars = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            use_japanese = 1;
        } else if (strcmp(argv[i], "-f") == 0) {
            force_term = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            linux_mode = 1;
        } else if (strcmp(argv[i], "-L") == 0) {
            lock_mode = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            old_style = 1;
        } else if (strcmp(argv[i], "-n") == 0) {
            no_bold = 1;
            bold_chars = 0;
            all_bold = 0;
        } else if (strcmp(argv[i], "-s") == 0) {
            screensaver_mode = 1;
        } else if (strcmp(argv[i], "-x") == 0) {
            x_mode = 1;
        } else if (strcmp(argv[i], "-r") == 0) {
            rainbow = 1;
        } else if (strcmp(argv[i], "-m") == 0) {
            lambda_mode = 1;
        } else if (strcmp(argv[i], "-k") == 0) {
            change_chars = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 < argc) {
                delay = atoi(argv[++i]);
                if (delay > MAX_DELAY) delay = MAX_DELAY;
                if (delay < MIN_DELAY) delay = MIN_DELAY;
            }
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 < argc) {
                color = argv[++i];
                current_color = parse_color(color);
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 < argc) {
                message = argv[++i];
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) {
                tty = argv[++i];
            }
        }
    }
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);

    if (x_mode) {
        printf("X window mode not supported in this version\n");
        return 0;
    }

    if (lock_mode) {
        printf("Lock mode not fully implemented\n");
    }

    init_terminal();

    srand(time(NULL));

    main_loop();

    restore_terminal();

    return 0;
}
